SELECT PO.*, CASE WHEN REC.received_date IS NOT NULL THEN CAST(REC.received_date AS DATE) ELSE CAST('1111-11-11' AS DATE) END AS RECIV_DATE
FROM (SELECT t1.po_nbr AS PO_NBR, t2.line_nbr AS LINE,
	     t1.order_date AS PO_DATE, t1.sams_po_type AS TYPE, 
	     t1.ship_date AS SHIP_DATE, t1.cancel_date AS CANCEL_DATE, 
	     t1.original_cancel_dt AS ORG_CANCEL_DATE, 
	     t1.po_status AS PO_ST, 
	     t1.ENTRY_COMP_INIT AS USR, 
	     t1.vendor_nbr AS VENDOR, 
	     t1.VENDOR_NBR_DEPT AS VENDOR_DET,
	     t1.VENDOR_NBR_SEQ AS VENDOR_SEQ, 
	     t1.vendor_name AS VENDOR_NAME, 
	     t2.seg_status AS ST_LINE, 
	     t1.store_nbr AS CEDIS, 
	     t3.category_nbr AS CAT, 
	     t3.sub_category_nbr AS S_CAT,
	     t3.old_nbr AS ITEM,
	     t3.primary_desc AS `DESC`, 
	     t3.majority_status_cd AS STATUS_ITEM, 
	     t1.event_desc AS EVENTO,
	     t2.whpk_order AS QTY_ORDER, 
	     t2.whpk_qty_rcvd AS QTY_RCVD, 
	     t2.net_vnpk_cost AS VNPK_COST, 
	     t2.vendor_pack_qty AS VNPK, 
	SUM(t2.net_vnpk_cost / t2.vendor_pack_qty * t2.whpk_order) AS TOTAL_COST_ORD, 
	SUM(t2.net_vnpk_cost / t2.vendor_pack_qty * t2.whpk_qty_rcvd) AS TOTAL_COST_REC
        FROM `wmt-edw-prod.MX_WC_VM.PURCHASE_ORDER` AS t1,
            `wmt-edw-prod.MX_WC_VM.PO_LINE` AS t2,
            `wmt-edw-prod.MX_WC_VM.ITEM_DESC` AS t3
        WHERE t1.po_nbr = t2.po_nbr AND t1.order_date = t2.order_date AND
	      t2.item_nbr = t3.item_nbr AND 
	      --t1.sams_po_type IN (20) AND
	      t1.order_date BETWEEN '2023-11-01' AND '2023-11-30' 
	   AND t2.whpk_order > 0 --AND t3.category_nbr IN (15, 60)
     AND t1.store_nbr IN (8118,
